1	//! Chat input: a multi-line, Piton-highlighted editor on the left and a send
2	//! button on the right, in the body of the Code, +, and Spec tabs. Enter adds a
3	//! line; Ctrl/Cmd+Enter sends, or queues the prompt while the harness works.
4	//! Tab and Shift+Tab cycle the tabs and Esc takes focus out of the input.
5	
6	use std::rc::Rc;
7	use std::sync::Arc;
8	
9	use gpui_kit::Focusable as _;
10	use gpui_kit::assets::IconName;
11	use gpui_kit::component::button::{Button, ButtonVariants};
12	use gpui_kit::component::input::{
13	    CompletionProvider, Editor, EditorState, Enter, Escape, IndentInline, InputEvent, MoveDown,
14	    MoveUp, OutdentInline, Rope,
15	};
16	use gpui_kit::component::tab::{Tab, TabBar};
17	use gpui_kit::component::{ActiveTheme, Disableable};
18	use gpui_kit::prelude::FluentBuilder as _;
19	use gpui_kit::*;
20	use lsp_types::{CompletionContext, CompletionResponse};
21	
22	use crate::completion_menu::CompletionMenu;
23	use crate::harness_mentions;
24	use crate::main_window::FocusChat;
25	use crate::piton_lsp::PitonSession;
26	use crate::piton_syntax;
27	use crate::project_directory::ProjectDirectory;
28	use crate::project_lsp::ProjectLsp;
29	
30	/// The input grows with its text up to this many rows, then scrolls.
31	const MAX_ROWS: usize = 12;
32	
33	/// Room the editor keeps free at the right of each line when soft wrapping.
34	const WRAP_RIGHT_MARGIN: Pixels = px(10.);
35	
36	#[cfg(target_os = "macos")]
37	const SEND_SHORTCUT: &str = "⌘Enter";
38	#[cfg(not(target_os = "macos"))]
39	const SEND_SHORTCUT: &str = "Ctrl+Enter";
40	
41	/// The tabs the input sits in, in the order Tab cycles them.
42	const TABS: [SendMode; 3] = [SendMode::Code, SendMode::Both, SendMode::Spec];
43	
44	/// The side of the square chain tab, half the height of the tabs.
45	const BOTH_TAB_SIZE: Pixels = px(16.);
46	
47	/// Index of the chain tab in `TABS`.
48	const BOTH_TAB: usize = 1;
49	
50	/// What a prompt is sent to work on: the selected tab.
51	#[derive(Clone, Copy, Debug, PartialEq)]
52	pub enum SendMode {
53	    Code,
54	    /// The code and the spec together.
55	    Both,
56	    Spec,
57	}
58	
59	impl SendMode {
60	    fn label(self) -> &'static str {
61	        match self {
62	            SendMode::Code => "Code",
63	            SendMode::Both => "Code and Spec",
64	            SendMode::Spec => "Spec",
65	        }
66	    }
67	
68	    fn id(self) -> &'static str {
69	        match self {
70	            SendMode::Code => "code-tab",
71	            SendMode::Both => "both-tab",
72	            SendMode::Spec => "spec-tab",
73	        }
74	    }
75	}
76	
77	/// Emitted with the input's text, and the mode it is sent in, when the user
78	/// sends it.
79	pub struct Submit {
80	    pub text: String,
81	    pub mode: SendMode,
82	}
83	
84	pub struct ChatInput {
85	    editor: Entity<EditorState>,
86	    completion: Entity<CompletionMenu>,
87	    /// The tab bar and its body, which Esc moves focus to: out of the input,
88	    /// but not onto nothing, where the window would hand it straight back.
89	    focus_handle: FocusHandle,
90	    /// Index into `TABS`.
91	    selected_tab: usize,
92	    lsp: Option<Arc<PitonSession>>,
93	    busy: bool,
94	    /// Width the editor's text was last laid out in, which decides where long
95	    /// lines soft wrap.
96	    text_width: Option<Pixels>,
97	    /// What the editor adds around its rows (padding and border) as last
98	    /// laid out, rounded to device pixels.
99	    chrome: Option<Pixels>,
100	    _subscriptions: Vec<Subscription>,
101	}
102	
103	impl EventEmitter<Submit> for ChatInput {}
104	
105	impl ChatInput {
106	    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
107	        let editor = cx.new(|cx| {
108	            EditorState::new(window, cx)
109	                .language(piton_syntax::LANGUAGE_NAME)
110	                .line_number(false)
111	                .folding(false)
112	                .soft_wrap(true)
113	                // No empty rows below the last line: the input is sized to its
114	                // text, so any extra would be blank space, and it would leave
115	                // room for the editor to stay scrolled past the first line
116	                // after Enter grows the input.
117	                .scroll_beyond_last_line(Some(0))
118	                .placeholder(format!(
119	                    "Write a prompt… (/ for skills and commands, @ for agents, {SEND_SHORTCUT} to send)"
120	                ))
121	        });
122	        // Typing goes straight into the input, without clicking it first.
123	        editor.read(cx).focus_handle(cx).focus(window, cx);
124	        let completion = cx.new(|cx| CompletionMenu::new(editor.clone(), window, cx));
125	
126	        let subscriptions = vec![
127	            cx.subscribe_in(&editor, window, |this, editor, event: &InputEvent, window, cx| {
128	                if matches!(event, InputEvent::Change) {
129	                    // An edit may be an accepted completion, whose import the
130	                    // hidden anchor then takes on.
131	                    if let Some(lsp) = &this.lsp {
132	                        lsp.note_edit(&editor.read(cx).value());
133	                    }
134	                    this.completion
135	                        .update(cx, |menu, cx| menu.on_edit(window, cx));
136	                }
137	                // Re-render on every edit so the input can grow to fit its text.
138	                cx.notify();
139	            }),
140	            cx.observe_global_in::<ProjectLsp>(window, |this, _, cx| this.connect_lsp(cx)),
141	        ];
142	
143	        let mut this = Self {
144	            editor,
145	            completion,
146	            focus_handle: cx.focus_handle(),
147	            selected_tab: 0,
148	            lsp: None,
149	            busy: false,
150	            text_width: None,
151	            chrome: None,
152	            _subscriptions: subscriptions,
153	        };
154	        this.connect_lsp(cx);
155	        this
156	    }
157	
158	    /// The project's `piton lsp` session, once it is running.
159	    pub fn lsp(&self) -> Option<Arc<PitonSession>> {
160	        self.lsp.clone()
161	    }
162	
163	    /// Moves keyboard focus into the input.
164	    pub fn focus(&mut self, window: &mut Window, cx: &mut Context<Self>) {
165	        self.editor.read(cx).focus_handle(cx).focus(window, cx);
166	    }
167	
168	    /// Inserts a harness mention at the cursor, after a space when the cursor
169	    /// follows other text, then moves focus into the input.
170	    pub fn insert_mention(&mut self, mention: &str, window: &mut Window, cx: &mut Context<Self>) {
171	        self.editor.update(cx, |editor, cx| {
172	            let value = editor.value();
173	            let follows_text = value
174	                .get(..editor.cursor())
175	                .and_then(|before| before.chars().next_back())
176	                .is_some_and(|c| !c.is_whitespace());
177	            let text = if follows_text {
178	                format!(" {mention}")
179	            } else {
180	                mention.to_string()
181	            };
182	            editor.insert(text, window, cx);
183	        });
184	        self.focus(window, cx);
185	    }
186	
187	    #[cfg(test)]
188	    pub fn value(&self, cx: &App) -> SharedString {
189	        self.editor.read(cx).value()
190	    }
191	
192	    #[cfg(test)]
193	    pub fn is_focused(&self, window: &Window, cx: &App) -> bool {
194	        self.editor.read(cx).focus_handle(cx).is_focused(window)
195	    }
196	
197	    /// Marks the harness as working; sending then queues the prompt.
198	    pub fn set_busy(&mut self, busy: bool, cx: &mut Context<Self>) {
199	        self.busy = busy;
200	        cx.notify();
201	    }
202	
203	    /// Points completions at the project's `piton lsp`, once it is running.
204	    /// Harness mentions complete without it.
205	    fn connect_lsp(&mut self, cx: &mut Context<Self>) {
206	        let client = ProjectLsp::get(cx);
207	        let connected = self.lsp.as_ref().map(|lsp| Arc::as_ptr(lsp.client()));
208	        if client.as_ref().map(Arc::as_ptr) == connected {
209	            return;
210	        }
211	        self.lsp = client.map(|client| Arc::new(PitonSession::new(client)));
212	        self.set_completions(self.lsp.clone(), cx);
213	    }
214	
215	    fn set_completions(&mut self, lsp: Option<Arc<PitonSession>>, cx: &mut Context<Self>) {
216	        let completions = Rc::new(PromptCompletions { lsp });
217	        self.completion
218	            .update(cx, |menu, cx| menu.set_provider(completions, cx));
219	    }
220	
221	    fn submit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
222	        let text = self.editor.read(cx).value().to_string();
223	        if text.is_empty() {
224	            return;
225	        }
226	        self.editor
227	            .update(cx, |editor, cx| editor.set_value("", window, cx));
228	        cx.emit(Submit {
229	            text,
230	            mode: TABS[self.selected_tab],
231	        });
232	    }
233	
234	    /// Selects a clicked tab and puts focus back in the input.
235	    fn select_tab(&mut self, ix: usize, window: &mut Window, cx: &mut Context<Self>) {
236	        self.selected_tab = ix;
237	        self.focus(window, cx);
238	        cx.notify();
239	    }
240	
241	    /// Moves `step` tabs along, wrapping around. An open completion menu
242	    /// keeps its own Tab and Shift+Tab.
243	    fn cycle_tab(&mut self, step: isize, cx: &mut Context<Self>) {
244	        if self.completion.read(cx).is_open() {
245	            return;
246	        }
247	        cx.stop_propagation();
248	        let count = TABS.len() as isize;
249	        self.selected_tab = (self.selected_tab as isize + step).rem_euclid(count) as usize;
250	        cx.notify();
251	    }
252	
253	    /// Esc closes an open completion menu, and otherwise takes focus out of
254	    /// the input.
255	    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) {
256	        if self.completion.read(cx).is_open() {
257	            self.completion.update(cx, |menu, cx| menu.hide(cx));
258	        } else {
259	            self.focus_handle.focus(window, cx);
260	        }
261	    }
262	
263	    /// The rows `text` takes in the editor: one per line, plus one for every
264	    /// soft wrap, wrapped the way the editor wraps it.
265	    fn visual_rows(&self, text: &str, window: &Window, cx: &App) -> usize {
266	        let Some(wrap_width) = self.text_width.map(|width| width - WRAP_RIGHT_MARGIN) else {
267	            return text.split('\n').count();
268	        };
269	        let theme = cx.theme();
270	        let mut wrapper = window
271	            .text_system()
272	            .line_wrapper(font(theme.mono_font_family.clone()), theme.mono_font_size);
273	        text.split('\n')
274	            .map(|line| {
275	                1 + wrapper
276	                    .wrap_line(&[LineFragment::text(line)], wrap_width)
277	                    .count()
278	            })
279	            .sum()
280	    }
281	}
282	
283	impl Render for ChatInput {
284	    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
285	        let text = self.editor.read(cx).value();
286	        let rows = self.visual_rows(&text, window, cx).clamp(1, MAX_ROWS);
287	        // Fit the text with the editor's own metrics: its laid-out line height
288	        // plus the padding and border around its rows. Until the editor has
289	        // painted, the border is estimated at a device pixel or more per side.
290	        let line_height = self
291	            .editor
292	            .read(cx)
293	            .line_height()
294	            .unwrap_or_else(|| window.line_height());
295	        let chrome = self.chrome.unwrap_or_else(|| {
296	            gpui_kit::component::Size::Medium.input_py() * 2.
297	                + ceil_to_device_pixel(px(1.), window) * 2.
298	        });
299	        let height = ceil_to_device_pixel(line_height * rows as f32 + chrome, window);
300	        let one_row = ceil_to_device_pixel(line_height + chrome, window);
301	        let empty = text.is_empty();
302	
303	        // Once the editor has painted, check how it was laid out: the width
304	        // its text wrapped in (a resized window wraps long lines differently)
305	        // and the padding and border around its rows. When either changed,
306	        // the input re-fits.
307	        let this = cx.entity().downgrade();
308	        let editor = self.editor.clone();
309	        let track_layout = canvas(
310	            |_, _, _| {},
311	            move |bounds, _, _, cx| {
312	                let Some(text_bounds) = editor.read(cx).text_bounds() else {
313	                    return;
314	                };
315	                let width = text_bounds.size.width;
316	                let chrome = bounds.size.height - text_bounds.size.height;
317	                this.update(cx, |this, cx| {
318	                    let chrome_changed = this
319	                        .chrome
320	                        .is_none_or(|old| (old - chrome).abs() > px(0.01));
321	                    if this.text_width != Some(width) || chrome_changed {
322	                        this.text_width = Some(width);
323	                        if chrome_changed {
324	                            this.chrome = Some(chrome);
325	                        }
326	                        cx.notify();
327	                    }
328	                })
329	                .ok();
330	            },
331	        )
332	        .absolute()
333	        .size_full();
334	
335	        // Code and Spec are full tabs side by side, each its own bar, and the
336	        // chain is a small square button laid over the seam between them: broken
337	        // until selected, then joined. Selecting it selects both tabs and covers
338	        // the seam, so they read as one tab.
339	        let selected = self.selected_tab;
340	        let unified = selected == BOTH_TAB;
341	        let chat_input = cx.entity().downgrade();
342	        let full_tab = |ix: usize| {
343	            let chat_input = chat_input.clone();
344	            let bar = TabBar::new(TABS[ix].id())
345	                .on_click(move |_, window, cx| {
346	                    chat_input
347	                        .update(cx, |this, cx| this.select_tab(ix, window, cx))
348	                        .ok();
349	                })
350	                .child(Tab::new().label(TABS[ix].label()).px_2());
351	            if selected == ix || unified {
352	                bar.selected_index(0)
353	            } else {
354	                bar
355	            }
356	        };
357	        let both = Button::new("both")
358	            .outline()
359	            .icon(if unified {
360	                IconName::Link
361	            } else {
362	                IconName::Unlink
363	            })
364	            .tooltip(SendMode::Both.label())
365	            .size(BOTH_TAB_SIZE)
366	            .on_click(cx.listener(|this, _, window, cx| this.select_tab(BOTH_TAB, window, cx)));
367	        let both = if unified { both.primary() } else { both };
368	        // An invisible copy of the Code tab bar puts the seam, whatever width
369	        // Code's label takes, and the chain is painted over both tabs from there.
370	        let seam = div()
371	            .absolute()
372	            .left_0()
373	            .top_0()
374	            .bottom_0()
375	            .flex()
376	            .child(
377	                TabBar::new("code-tab-width")
378	                    .child(Tab::new().label(SendMode::Code.label()).px_2())
379	                    .invisible(),
380	            )
381	            .child(
382	                div()
383	                    .relative()
384	                    .w_0()
385	                    .flex()
386	                    .items_center()
387	                    // The selected tabs' facing borders, covered.
388	                    .when(unified, |this| {
389	                        this.child(
390	                            div()
391	                                .absolute()
392	                                .top_0()
393	                                .bottom_0()
394	                                .left(px(-1.))
395	                                .w(px(2.))
396	                                .bg(cx.theme().tab_active),
397	                        )
398	                    })
399	                    .child(
400	                        div().relative().w_0().h(BOTH_TAB_SIZE).child(
401	                            gpui_kit::TestSupportExt::test_support(
402	                                div()
403	                                    .id(SendMode::Both.id())
404	                                    .absolute()
405	                                    .top_0()
406	                                    .left(BOTH_TAB_SIZE * -0.5)
407	                                    .rounded(cx.theme().radius)
408	                                    .bg(cx.theme().background)
409	                                    .child(both),
410	                            ),
411	                        ),
412	                    ),
413	            );
414	        let tabs = gpui_kit::TestSupportExt::test_support(
415	            div()
416	                .id("chat-tabs")
417	                .relative()
418	                .flex()
419	                .items_center()
420	                .bg(cx.theme().tab_bar)
421	                .child(
422	                    div()
423	                        .absolute()
424	                        .left_0()
425	                        .bottom_0()
426	                        .size_full()
427	                        .border_b_1()
428	                        .border_color(cx.theme().border),
429	                )
430	                .child(full_tab(0))
431	                .child(full_tab(2).flex_1())
432	                .child(seam),
433	        );
434	
435	        let body = div().flex().flex_row().items_end().gap_2().p_3();
436	
437	        div()
438	            .track_focus(&self.focus_handle)
439	            .flex()
440	            .flex_col()
441	            .border_t_1()
442	            .border_color(cx.theme().border)
443	            // Tab and Shift+Tab cycle the tabs rather than indenting, and the
444	            // input keeps focus.
445	            .capture_action(cx.listener(|this, _: &IndentInline, _, cx| this.cycle_tab(1, cx)))
446	            .capture_action(cx.listener(|this, _: &OutdentInline, _, cx| this.cycle_tab(-1, cx)))
447	            // Esc arrives as the window's FocusChat, which matches ahead of the
448	            // editor's own binding, or as the editor's Escape once it has
449	            // nothing to cancel. Handled here, neither reaches the window,
450	            // which would focus the input again.
451	            .on_action(cx.listener(|this, _: &FocusChat, window, cx| this.escape(window, cx)))
452	            .on_action(cx.listener(|this, _: &Escape, window, cx| this.escape(window, cx)))
453	            .capture_action(cx.listener(|this, action: &Enter, window, cx| {
454	                // Catch Ctrl/Cmd+Enter before the editor turns it into a newline.
455	                if action.secondary {
456	                    cx.stop_propagation();
457	                    this.submit(window, cx);
458	                } else if this.completion.read(cx).is_open() {
459	                    // Enter accepts the completion instead of adding a line.
460	                    cx.stop_propagation();
461	                    this.completion
462	                        .update(cx, |menu, cx| menu.accept_selected(window, cx));
463	                }
464	            }))
465	            // Up and Down move through an open completion menu instead of
466	            // the text.
467	            .capture_action(cx.listener(|this, _: &MoveUp, window, cx| {
468	                if this.completion.read(cx).is_open() {
469	                    cx.stop_propagation();
470	                    this.completion
471	                        .update(cx, |menu, cx| menu.select_next(-1, window, cx));
472	                }
473	            }))
474	            .capture_action(cx.listener(|this, _: &MoveDown, window, cx| {
475	                if this.completion.read(cx).is_open() {
476	                    cx.stop_propagation();
477	                    this.completion
478	                        .update(cx, |menu, cx| menu.select_next(1, window, cx));
479	                }
480	            }))
481	            .child(tabs)
482	            .child(
483	                body.child(gpui_kit::TestSupportExt::test_support(
484	                    div()
485	                        .id("prompt-editor")
486	                        .relative()
487	                        .flex_1()
488	                        .min_w_0()
489	                        .child(Editor::new(&self.editor).h(height))
490	                        .child(track_layout)
491	                        .child(self.completion.clone()),
492	                ))
493	                .child(
494	                    Button::new("send")
495	                        .primary()
496	                        // While the harness works, sending queues the prompt.
497	                        .label(if self.busy { "Queue" } else { "Send" })
498	                        // As tall as the input's single line, so the two line up.
499	                        .h(one_row)
500	                        .tooltip(if self.busy {
501	                            format!("Queue until the harness is free ({SEND_SHORTCUT})")
502	                        } else {
503	                            format!("Send ({SEND_SHORTCUT})")
504	                        })
505	                        .disabled(empty)
506	                        .on_click(cx.listener(|this, _, window, cx| this.submit(window, cx))),
507	                ),
508	            )
509	    }
510	}
511	
512	/// Completions for the chat input: harness mentions after `/` or `@`, and
513	/// Piton from `piton lsp`, when it is running, everywhere else.
514	struct PromptCompletions {
515	    lsp: Option<Arc<PitonSession>>,
516	}
517	
518	impl CompletionProvider for PromptCompletions {
519	    fn completions(
520	        &self,
521	        text: &Rope,
522	        offset: usize,
523	        _: CompletionContext,
524	        _: &mut Window,
525	        cx: &mut App,
526	    ) -> Task<Result<CompletionResponse>> {
527	        let lsp = self.lsp.clone();
528	        let prompt = text.to_string();
529	        let project_dir = ProjectDirectory::get(cx);
530	        cx.background_spawn(async move {
531	            if harness_mentions::mention_at(&prompt, offset).is_some() {
532	                let invocables = harness_mentions::discover(project_dir.as_deref());
533	                let items = harness_mentions::complete(&prompt, offset, &invocables);
534	                return Ok(CompletionResponse::Array(items.unwrap_or_default()));
535	            }
536	            // A slash or hyphen only triggers completion inside a mention.
537	            let typed = prompt
538	                .get(..offset)
539	                .and_then(|before| before.chars().next_back());
540	            match lsp {
541	                Some(lsp) if !matches!(typed, Some('/' | '-')) => lsp.complete(&prompt, offset),
542	                _ => Ok(CompletionResponse::Array(Vec::new())),
543	            }
544	        })
545	    }
546	
547	    fn is_completion_trigger(&self, _: usize, new_text: &str, _: &mut App) -> bool {
548	        new_text.chars().last().is_some_and(|c| {
549	            c.is_alphanumeric() || matches!(c, '{' | '.' | '$' | '@' | ':' | '_' | '/' | '-')
550	        })
551	    }
552	}
553	
554	/// Rounds `length` up to a whole device pixel. Layout rounds lengths to
555	/// device pixels half toward zero, so at fractional scales an input sized in
556	/// logical pixels can come out a fraction of a pixel short of its rows; the
557	/// editor then takes its last row for out of view and scrolls it in for a
558	/// frame, which flickers the text a line up and back.
559	fn ceil_to_device_pixel(length: Pixels, window: &Window) -> Pixels {
560	    let scale_factor = window.scale_factor();
561	    // Float noise just past a whole device pixel must not round up to the next.
562	    px((f32::from(length) * scale_factor - 1e-3).ceil() / scale_factor)
563	}
