565	#[cfg(test)]
566	mod tests {
567	    // Explicit imports: globbing `gpui_kit::*` would bring in GPUI's `test`
568	    // macro and shadow Rust's `#[test]`.
569	    use std::cell::Cell;
570	    use std::path::PathBuf;
571	    use std::rc::Rc;
572	    use std::time::Duration;
573	
574	    use gpui_kit::component::Root;
575	    use gpui_kit::test::{TestAppContextExt as _, TestWindowExt as _};
576	    use gpui_kit::{
577	        AppContext as _, Context, Entity, Focusable as _, IntoElement, ParentElement as _, Render,
578	        Styled as _, TestAppContext, Window, div,
579	    };
