893	    /// The chat input at the bottom of the window, with a probe laid out
894	    /// after it that notes the editor's scroll offset between prepaint and
895	    /// paint: the offset its text is actually painted at, before paint
896	    /// clamps it for the next frame.
897	    struct Probed {
898	        input: Entity<ChatInput>,
899	        painted_scroll_y: Rc<Cell<gpui_kit::Pixels>>,
900	    }
901	
902	    impl Render for Probed {
903	        fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
904	            let editor = self.input.read(cx).editor.clone();
905	            let painted_scroll_y = self.painted_scroll_y.clone();
906	            div()
907	                .size_full()
908	                .flex()
909	                .flex_col()
910	                .justify_end()
911	                .child(self.input.clone())
912	                .child(
913	                    gpui_kit::canvas(
914	                        move |_, _, cx| painted_scroll_y.set(editor.read(cx).scroll_offset().y),
915	                        |_, _, _, _| {},
916	                    )
917	                    .absolute()
918	                    .size_0(),
919	                )
920	        }
921	    }
