923	    /// What one painted frame of the input looked like.
924	    #[derive(Debug, Clone, Copy)]
925	    struct Frame {
926	        rows: usize,
927	        top: gpui_kit::Pixels,
928	        bottom: gpui_kit::Pixels,
929	        height: gpui_kit::Pixels,
930	        /// The offset the text was painted at in this frame.
931	        painted_scroll_y: gpui_kit::Pixels,
932	        /// The offset the editor kept after painting.
933	        scroll_y: gpui_kit::Pixels,
934	        cursor_top: gpui_kit::Pixels,
935	        cursor_bottom: gpui_kit::Pixels,
936	    }
937	
938	    /// Presses Enter in the input at the bottom of the window, `presses`
939	    /// times, and records every frame drawn after each press, the way the
940	    /// window draws them: only what the press invalidated, with no forced
941	    /// refresh in between.
942	    async fn frames_after_enter(
943	        presses: usize,
944	        scale_factor: f32,
945	        cx: &mut TestAppContext,
946	    ) -> (gpui_kit::Pixels, Vec<Vec<Frame>>) {
947	        cx.update(|cx| {
948	            gpui_kit::init(cx);
949	            piton_syntax::init();
950	            ProjectDirectory::init(cx);
951	        });
952	        let mut chat_input = None;
953	        let painted = Rc::new(Cell::new(gpui_kit::px(0.)));
954	        let window = cx.add_window(|window, cx| {
955	            let input = cx.new(|cx| ChatInput::new(window, cx));
956	            chat_input = Some(input.clone());
957	            let painted_scroll_y = painted.clone();
958	            let view = cx.new(|_| Probed {
959	                input,
960	                painted_scroll_y,
961	            });
962	            Root::new(view, window, cx)
963	        });
964	        let chat_input = chat_input.unwrap();
965	        let editor = chat_input.read_with(cx, |input, _| input.editor.clone());
966	        let handle = window.into();
967	        // Most displays are not 2x: at other scales the rows are a fraction
968	        // of a pixel off the device grid.
969	        cx.simulate_window_scale_factor_change(handle, scale_factor);
970	        cx.wait_for(handle, TIMEOUT, |_, cx| {
971	            editor.read(cx).line_height().is_some()
972	        })
973	        .await;
974	
975	        let record = |window: &mut Window, cx: &mut gpui_kit::App| {
976	            window.draw(cx).clear(cx);
977	            let bounds = window.find("prompt-editor").bounds();
978	            let editor = editor.read(cx);
979	            let scroll_y = editor.scroll_offset().y;
980	            // The cursor is laid out in window coordinates, before scrolling.
981	            let (cursor, _) = editor.cursor_layout().unwrap();
982	            let painted_scroll_y = painted.get();
983	            Frame {
984	                rows: editor.value().split('\n').count(),
985	                top: bounds.top(),
986	                bottom: bounds.bottom(),
987	                height: bounds.size.height,
988	                painted_scroll_y,
989	                scroll_y,
990	                cursor_top: cursor.top() + painted_scroll_y,
991	                cursor_bottom: cursor.bottom() + painted_scroll_y,
992	            }
993	        };
994	
995	        cx.update_window(handle, |_, window, cx| {
996	            editor.read(cx).focus_handle(cx).focus(window, cx);
997	            window.render_frame(cx);
998	            window.render_frame(cx);
999	            window.input("x", cx);
1000	        })
1001	        .unwrap();
1002	        let line_height = editor.read_with(cx, |editor, _| editor.line_height().unwrap());
1003	
1004	        let mut presses_frames = vec![];
1005	        for _ in 0..presses {
1006	            let frames = cx
1007	                .update_window(handle, |_, window, cx| {
1008	                    let before = record(window, cx);
1009	                    window.dispatch_keystroke(gpui_kit::Keystroke::parse("enter").unwrap(), cx);
1010	                    let mut frames = vec![before];
1011	                    for _ in 0..6 {
1012	                        frames.push(record(window, cx));
1013	                    }
1014	                    frames
1015	                })
1016	                .unwrap();
1017	            cx.run_until_parked();
1018	            presses_frames.push(frames);
1019	        }
1020	        (line_height, presses_frames)
1021	    }
