1023	    /// Enter grows the input by one row in the very next frame, and it stays
1024	    /// put from then on: the bottom edge never moves, the first line never
1025	    /// scrolls out of view, and the cursor is always inside the input.
1026	    async fn assert_enter_grows_without_flicker(scale_factor: f32, cx: &mut TestAppContext) {
1027	        let (line_height, presses) = frames_after_enter(MAX_ROWS + 3, scale_factor, cx).await;
1028	        let bottom = presses[0][0].bottom;
1029	        let one_row = presses[0][0].height;
1030	        for (press, frames) in presses.iter().enumerate() {
1031	            let rows = frames.last().unwrap().rows;
1032	            let expected = one_row + line_height * (rows.min(MAX_ROWS) - 1) as f32;
1033	            for (ix, frame) in frames.iter().enumerate().skip(1) {
1034	                let context = format!(
1035	                    "at {scale_factor}x, line height {line_height:?}, press {press}, frame {ix} of {frames:#?}"
1036	                );
1037	                assert!(
1038	                    (frame.height - expected).abs() <= gpui_kit::px(0.5),
1039	                    "height is not {expected:?} rows: {context}"
1040	                );
1041	                assert!(
1042	                    (frame.bottom - bottom).abs() <= gpui_kit::px(0.5),
1043	                    "the bottom edge moved from {bottom:?}: {context}"
1044	                );
1045	                if rows <= MAX_ROWS {
1046	                    assert!(
1047	                        frame.painted_scroll_y.abs() <= gpui_kit::px(0.5),
1048	                        "painted scrolled although everything fits: {context}"
1049	                    );
1050	                } else {
1051	                    assert!(
1052	                        (frame.painted_scroll_y - frames.last().unwrap().painted_scroll_y).abs()
1053	                            <= gpui_kit::px(0.5),
1054	                        "scroll did not settle in the first frame: {context}"
1055	                    );
1056	                }
1057	                assert!(
1058	                    frame.cursor_top >= frame.top - gpui_kit::px(0.5)
1059	                        && frame.cursor_bottom <= frame.bottom + gpui_kit::px(0.5),
1060	                    "the cursor is outside the input: {context}"
1061	                );
1062	            }
1063	        }
1064	    }
