    cx.update_window(handle, |_, window, cx| window.press("shift-tab", cx))
        .unwrap();
    let (_, chain, _) = settle_chain(handle, super::CHAIN_GAP, cx);
    assert_eq!(chain, resting, "the chain moved when deactivated");
}

